// Zona horaria local
const TZ = 'America/Argentina/Buenos_Aires';

function nowInTZ(tz) {
 // Método más confiable usando Intl.DateTimeFormat
 const now = new Date();
 const formatter = new Intl.DateTimeFormat('en-CA', {
 timeZone: tz,
 year: 'numeric',
 month: '2-digit',
 day: '2-digit',
 hour: '2-digit',
 minute: '2-digit',
 second: '2-digit',
 hour12: false
 });

 const parts = formatter.formatToParts(now);
 const dateStr = ${parts[0].value}-${parts[2].value}-${parts[4].value}T${parts[6].value}:${parts[8].value}:${parts[10].value};
 return new Date(dateStr);
}

function setTime(d, h, m = 0) {
 const nd = new Date(d);
 nd.setHours(h, m, 0, 0);
 return nd;
}

function addDays(d, n) {
 const nd = new Date(d);
 nd.setDate(nd.getDate() + n);
 return nd;
}

function nextWeekdayAt08(d) {
 // Avanza al próximo día hábil a las 08:00
 let n = addDays(d, 1);
 while ([0, 6].includes(n.getDay())) { // 0=Dom, 6=Sab
 n = addDays(n, 1);
 }
 return setTime(n, 8, 0);
}

const now = nowInTZ(TZ);
const day = now.getDay(); // 0..6 (0=Dom)
const hour = now.getHours();
const minute = now.getMinutes();

// Ventana: Lun-Vie 08:00–18:00 (18:00 excluido)
let isOpen = false;
if (day >= 1 && day <= 5) {
 // Simplificado: está abierto si es >= 08:00 y < 18:00
 const timeInMinutes = hour * 60 + minute;
 const openTime = 8 * 60; // 08:00 en minutos
 const closeTime = 18 * 60; // 18:00 en minutos

 isOpen = timeInMinutes >= openTime && timeInMinutes < closeTime;
}

// Calcular próxima apertura (si está cerrado)
let nextOpen;
if (isOpen) {
 nextOpen = now; // Técnicamente no se necesita, pero por completitud
} else {
 if (day >= 1 && day <= 5) {
 // Es día hábil pero fuera del horario
 if (hour < 8) {
 // Hoy antes de las 08:00 → hoy 08:00
 nextOpen = setTime(now, 8, 0);
 } else {
 // Hoy después de las 18:00 → próximo hábil 08:00
 nextOpen = nextWeekdayAt08(now);
 }
 } else {
 // Sábado/Domingo → próximo lunes (o hábil) 08:00
 nextOpen = nextWeekdayAt08(now);
 }
}

// Salida corregida
return [{
 json: {
 ...$json,
 now_local: now.toLocaleString('es-AR', { timeZone: TZ, hour12: false }),
 isOpen,
 nextOpenISO: nextOpen.toISOString(),
 nextOpenLocal: nextOpen.toLocaleString('es-AR', { timeZone: TZ, hour12: false }),
 }
}];

